insert into kkf_private.questions(quiz_version,question_id,position,subject,command,topic,topic_options,question,model,criteria,expected,unit) values
('kkf-v1','heat-transfer',1,'Physics','Explain','heat transfer','["heat transfer","air pressure","electrical resistance"]'::jsonb,'Explain why trapped air reduces heat transfer through a wall.','Air is a poor thermal conductor, so a trapped layer reduces energy transfer by conduction through the wall. Keeping the air trapped also limits convection.','["I identified trapped air as a poor thermal conductor (or said it limits convection).","I linked that property to slower energy transfer through the wall."]'::jsonb,null,null),
('kkf-v1','gradient',2,'Maths','Calculate','gradient','["area","gradient","probability"]'::jsonb,'Calculate the gradient of a straight line through (1, 3) and (5, 11).','Gradient = (11 − 3) ÷ (5 − 1) = 8 ÷ 4 = 2. The coordinates have no stated units, so the gradient has no unit here.','[]'::jsonb,2,'none'),
('kkf-v1','gas-motion',3,'Chemistry','Describe','gas particles','["gas particles","bonding","solubility"]'::jsonb,'Describe the motion of gas particles in a sealed, rigid container as the gas is heated.','The gas particles move randomly in all directions. As the gas is heated, their average speed increases.','["I stated that gas particles move randomly in all directions.","I stated that their average speed increases as the gas is heated."]'::jsonb,null,null),
('kkf-v1','linear-graphs',4,'Maths','Compare','graphs','["angles","graphs","fractions"]'::jsonb,'Compare the graphs of y = 2x + 1 and y = 2x + 4. Include one similarity and one difference.','Both graphs are straight lines with gradient 2, so they are parallel. The graph of y = 2x + 1 has y-intercept 1, whereas y = 2x + 4 has y-intercept 4.','["I gave a correct similarity that directly refers to both graphs.","I gave a correct difference between the two graphs (for example, their y-intercepts)."]'::jsonb,null,null),
('kkf-v1','expanding',5,'Maths','Explain','expanding brackets','["expanding brackets","solving inequalities","rounding"]'::jsonb,'Explain why expanding brackets in 3(x + 2) gives 3x + 6.','The distributive law means the 3 multiplies every term inside the brackets. Therefore 3(x + 2) = 3 × x + 3 × 2 = 3x + 6.','["I explained that 3 multiplies both terms inside the brackets.","I linked that rule to 3 × x = 3x and 3 × 2 = 6."]'::jsonb,null,null),
('kkf-v1','acceleration',6,'Physics','Calculate','acceleration','["density","acceleration","power"]'::jsonb,'Calculate the acceleration of a 4 kg trolley when a resultant force of 12 N acts on it.','F = ma, so a = F ÷ m = 12 ÷ 4 = 3 m/s².','[]'::jsonb,3,'m/s2'),
('kkf-v1','translation',7,'Maths','Describe','translation','["reflection","translation","rotation"]'::jsonb,'Describe the translation that maps (x, y) to (x − 3, y + 2).','Translate every point 3 units to the left and 2 units up. The translation vector is (−3, 2).','["I stated that every point moves 3 units to the left.","I stated that every point moves 2 units up."]'::jsonb,null,null),
('kkf-v1','cells',8,'Biology','Compare','plant and animal cells','["plant and animal cells","diffusion","food chains"]'::jsonb,'Compare typical plant and animal cells. Include one similarity and one difference.','Both typical plant and animal cells have a nucleus, cytoplasm and a cell membrane. A plant cell has a cellulose cell wall, whereas an animal cell has no cell wall.','["I gave a correct shared structure, such as a nucleus, cytoplasm or cell membrane.","I gave a correct structural difference, directly linking the two cell types."]'::jsonb,null,null)
